import type { AnimationManager } from "@babylonjs/lite";
import { updateAnimationManager } from "@babylonjs/lite";

export function skipAhead(manager: AnimationManager, ms: number): void {
    if (ms <= 0) return;

    const fixed = manager.fixedDeltaMs;
    if (fixed > 0) {
        const fullSteps = Math.floor(ms / fixed);
        const remainder = ms - fullSteps * fixed;
        for (let i = 0; i < fullSteps; i++) {
            updateAnimationManager(manager, fixed);
        }
        if (remainder > 0) {
            updateAnimationManager(manager, remainder);
        }
    } else {
        updateAnimationManager(manager, ms);
    }
}
```

This looks good. Let me verify:
- If `ms` is exactly a multiple of `fixedDeltaMs`, `remainder` will be 0 (or very close to 0 due to FP), and we just do the full steps.
- If `ms` is not a multiple, we do full steps plus one remainder step.
- If there's no fixed step (`fixedDeltaMs` is 0), we just pass `ms` directly.

One concern: floating point. If `ms = 100` and `fixed = 16.667`, then `100 / 16.667 = 5.9998...`, `Math.floor` gives 5, `remainder = 100 - 5 * 16.667 = 100 - 83.335 = 16.665`. That's correct - we've advanced by 5 full steps + one partial step = 100ms total.

The total advanced is `fullSteps * fixed + remainder = ms` (up to floating point precision). Good.

